def generate_output(input_grid):
    n = len(input_grid)
    output_rows = n // 2

    # Find position of last occurrence of leftmost value and last of rightmost
    leftmost_val = input_grid[0]
    rightmost_val = input_grid[-1]

    output = []
    for r in range(output_rows):
        row = []
        # Left boundary: positions 0 to leftmost_pos + r are leftmost_val
