def gen2(input_grid):
    n = len(input_grid)
    output_rows = n // 2
    leftmost_val = input_grid[0]
    rightmost_val = input_grid[-1]

    output = []
    for r in range(output_rows):
        row = []
        left_region_size = 3 + r  # 3 from input leftmost
        right_region_size = 15 - r  # 15 from input rightmost boundary

        for c in range(n):
            if c < left_region_size:
                row.append(leftmost_val)
            elif c >= n - right_region_size:
                row.append(rightmost_val)
            else:
                row.append(input_grid[c])
        output.append(row)
    return output

