def generate_output_v3(input_grid):
    n = len(input_grid)
    output_rows = n // 2

    output = []
    for r in range(output_rows):
        row = []
        for c in range(n):
            if c < r:
                row.append(input_grid[0])  # top value
            elif c < n - 1 - r:
                row.append(input_grid[c])
            else:
                row.append(input_grid[-1])  # rightmost value
        output.append(row)
    return output

