def generate_spread_leftonly(input_grid):
    n = len(input_grid)
    output_rows = n // 2
    leftmost = input_grid[0]

    output = []
    for r in range(output_rows):
        row = []
        # Leftmost spreads by r, rightmost stays
        for c in range(n):
            if c < r:
                row.append(leftmost)
            else:
                row.append(input_grid[c])
        output.append(row)
    return output

